prompt_text:
{
  "type": "multi-style comparative art grid",
  "subject": "single apple interpreted through eight different visual systems in one image",
  "composition": {
    "format": "square 3x3 grid",
    "canvas": "large square canvas",
    "background": "each cell uses its own appropriate background except the center cell, which is intentionally left blank",
    "center_cell": {
      "position": "middle center",
      "content": "empty white square negative space",
      "purpose": "clear visual gap separating the surrounding interpretations"
    },
    "cells": [
      {
        "position": "top left",
        "style": "Cézanne-inspired post-impressionist painting",
        "subject": "whole apple",
        "details": "a red-orange apple rendered with thick broken brushstrokes and palette-knife texture, mottled warm and cool color patches, blue-gray tabletop or ground, visible painterly shadow to the right, expressive impasto surface"
      },
      {
        "position": "top center",
        "style": "Dutch still life oil painting",
        "subject": "whole apple",
        "details": "a realistic red apple on a wooden ledge against a deep dark brown-black background, dramatic chiaroscuro lighting, subtle highlight on the fruit, classical museum-style still life atmosphere"
      },
      {
        "position": "top right",
        "style": "sumi-e ink painting",
        "subject": "apple suggested with minimal brushwork",
        "details": "off-white paper background, a few gestural gray-black ink strokes forming an incomplete circular apple silhouette, dark shaded crescent on one side, simple stem, red seal stamp in the lower right area of the cell, elegant East Asian calligraphic restraint"
      },
      {
        "position": "middle left",
        "style": "medical botanical diagram",
        "subject": "horizontal cross-section of an apple",
        "details": "vintage scientific illustration on aged ivory paper, centered halved apple with seeds and internal structure visible, fine line labels pointing to parts with readable Latin text including 'Pericarpium (exocarpium)', 'Mesocarpium', 'Endocarpium', and 'Loculus (seminifer)', with caption 'Malus domestica' and 'Sectio horizontalis' below"
      },
      {
        "position": "middle right",
        "style": "Warhol-inspired pop art screen print",
        "subject": "whole apple",
        "details": "bold simplified apple in saturated hot pink and magenta with dark outline, bright yellow upper background and cobalt blue lower background, high contrast graphic treatment, silkscreen poster aesthetic"
      },
      {
        "position": "bottom left",
        "style": "hyperreal macro photography",
        "subject": "extreme close-up apple detail",
        "details": "photographic macro view of the apple skin and stem cavity, crisp stem in sharp focus, glossy water droplet on the red peel, shallow depth of field, luminous texture and realistic specular highlights"
      },
      {
        "position": "bottom center",
        "style": "cubist painting",
        "subject": "whole apple",
        "details": "apple deconstructed into angular geometric planes in muted brown, ochre, and gray tones, faceted background and form merging together, subdued analytical cubism mood, stem visible at the top"
      },
      {
        "position": "bottom right",
        "style": "children's book illustration",
        "subject": "cute smiling apple character",
        "details": "friendly hand-painted watercolor and colored pencil style apple with rosy cheeks, simple black dot eyes, curved smile, small stem with green leaf, soft shadow beneath, playful storybook look"
      }
    ],
    "count": 8
  },
  "lighting": "each cell uses its own internally consistent lighting logic",
  "color_strategy": "distinct palette per cell to emphasize different representational grammars",
  "instructions": "Create a single unified image, not a collage assembled from separate files, depicting [one apple] through exactly 8 visual grammars arranged around an empty center. Keep the middle cell blank white. Maintain a strict 3x3 grid with 8 occupied cells and 1 empty center cell. Make each occupied cell a convincing exemplar of its style while preserving the same core subject.",
  "style_labels": [
    "[Cézanne]",
    "[Dutch still life]",
    "[Sumi-e]",
    "[Medical diagram]",
    "[Warhol]",
    "[Hyperreal macro]",
    "[Cubism]",
    "[Children's illustration]"
  ]
}

